1	<script lang="ts">
2		import '../app.css';
3		import { supabase } from '$lib/supabaseClient';
4		import { onMount } from 'svelte';
5		import { writable } from 'svelte/store';
6		import { SvelteURLSearchParams } from 'svelte/reactivity';
7		import { page } from '$app/stores';
8		import { resolve } from '$app/paths';
9		import { APP_VERSION } from '$lib/version';
10		import type { Snippet } from 'svelte';
11	
12		let { children }: { children: Snippet } = $props();
13	
14		type Session = Awaited<ReturnType<typeof supabase.auth.getSession>>['data']['session'];
15		const session = writable<Session | null>(null);
16		let authChecked = $state(false);
17	
18		// #{#ath1a} Public routes that do not require authentication
19		const publicRoutes = ['/', '/login', '/forgot-password', '/reset-password'];
20	
21		let isPublicRoute = $derived(publicRoutes.includes($page.url.pathname));
22	
23		onMount(() => {
24			// Subscribe synchronously so onMount can return a synchronous cleanup
25			// (an async onMount callback can't return a teardown function).
26			const { data: sub } = supabase.auth.onAuthStateChange((_e, s) => session.set(s));
27	
28			void (async () => {
29				const { data } = await supabase.auth.getSession();
30				session.set(data.session);
31				authChecked = true;
32			})();
33	
34			return () => {
35				sub.subscription.unsubscribe();
36			};
37		});
38	
39		async function logout() {
40			await supabase.auth.signOut();
41			window.location.href = '/login';
42		}
43	
44		// #{#sdf3a} Preserve date filter query parameters in navigation.
45		// `resolve()` only accepts a single concrete route literal, so each nav link
46		// branches `resolve(`/route?${filterQuery}`)` vs `resolve('/route')` (see the
47		// same pattern in expenses/+page.svelte). This derived is just the query body
48		// (no leading `?`), shared by every link.
49		let filterQuery = $derived.by(() => {
50			const params = $page.url.searchParams;
51			const dateFrom = params.get('dateFrom');
52			const dateTo = params.get('dateTo');
53	
54			const newParams = new SvelteURLSearchParams();
55			if (dateFrom) newParams.set('dateFrom', dateFrom);
56			if (dateTo) newParams.set('dateTo', dateTo);
57	
58			return newParams.toString();
59		});
60	</script>
61	
62	<div class="flex min-h-dvh flex-col">
63		<header class="sticky top-0 z-10 border-b bg-white/70 backdrop-blur">
64			<div class="mx-auto flex max-w-5xl items-center justify-between px-4 py-3">
65				<a href={resolve('/')} class="font-semibold">Family Receipts</a>
66				<div class="flex items-center gap-3">
67					<!-- #{#ath1a} Only show nav links when authenticated -->
68					{#if $session}
69						<a
70							href={filterQuery ? resolve(`/receipts?${filterQuery}`) : resolve('/receipts')}
71							class="text-sm hover:underline">Receipts</a
72						>
73						<a
74							href={filterQuery ? resolve(`/transactions?${filterQuery}`) : resolve('/transactions')}
75							class="text-sm hover:underline">Transactions</a
76						>
77						<a
78							href={filterQuery
79								? resolve(`/reconciliation?${filterQuery}`)
80								: resolve('/reconciliation')}
81							class="text-sm hover:underline">Reconciliation</a
82						>
83						<!-- #{#exp1a} Expenses tab navigation with filter preservation -->
84						<a
85							href={filterQuery ? resolve(`/expenses?${filterQuery}`) : resolve('/expenses')}
86							class="text-sm hover:underline"
87							class:font-semibold={$page.url.pathname.startsWith('/expenses')}
88							aria-current={$page.url.pathname.startsWith('/expenses') ? 'page' : undefined}
89						>
90							Expenses
91						</a>
92						<!-- Spending report navigation -->
93						<a
94							href={resolve('/spending')}
95							class="text-sm hover:underline"
96							class:font-semibold={$page.url.pathname.startsWith('/spending')}
97							aria-current={$page.url.pathname.startsWith('/spending') ? 'page' : undefined}
98						>
99							Spending
100						</a>
101						<!-- #{#upp1b} Profile link navigation -->
102						<a
103							href={resolve('/profile')}
104							class="text-sm hover:underline"
105							class:font-semibold={$page.url.pathname === '/profile'}
106							aria-current={$page.url.pathname === '/profile' ? 'page' : undefined}
107							aria-label="View profile"
108						>
109							Profile
110						</a>
111						<button class="rounded bg-gray-100 px-3 py-1 text-sm hover:bg-gray-200" onclick={logout}
112							>Logout</button
113						>
114					{:else}
115						<a href={resolve('/login')} class="text-sm hover:underline">Login</a>
116					{/if}
117					<span class="text-xs text-gray-500">v{APP_VERSION}</span>
118				</div>
119			</div>
120		</header>
121		<!-- The spending report is a wide grid; let it use the full window. Other pages
122		     keep a comfortable reading width. -->
123		<main
124			class="mx-auto flex-1 px-4 py-6 {$page.url.pathname.startsWith('/spending')
125				? 'max-w-full'
126				: 'max-w-5xl'}"
127		>
128			{#if isPublicRoute || $session}
129				{@render children()}
130			{:else if !authChecked}
131				<p class="text-center text-gray-500">Loading…</p>
132			{:else}
133				<!-- #{#ath1b} Not-logged-in message for unauthenticated users on protected routes -->
134				<div class="py-12 text-center">
135					<p class="text-lg text-gray-700">You are not logged in.</p>
136					<a
137						href={resolve('/login')}
138						class="mt-4 inline-block text-blue-600 underline hover:text-blue-800">Go to login</a
139					>
140				</div>
141			{/if}
142		</main>
143	</div>
