1	/**
2	 * Shared config + teardown for the demo-data seed.
3	 *
4	 * The demo seed populates a self-contained "Sample Family (DEMO)" — two auth
5	 * users, a family, categories/hierarchy, receipts and transactions — so the
6	 * running app can be logged into for documentation screenshots/videos and
7	 * manual testing. See docs/demo-seed.md.
8	 *
9	 * Everything here is keyed off the two demo emails and the demo family name, so
10	 * teardown can only ever touch demo artifacts, never real data. All access uses
11	 * the service-role key (bypasses RLS).
12	 *
13	 * **Local only.** The demo family used to be seeded into the remote project too;
14	 * it was torn down there on 2026-07-26 and the remote npm scripts were removed.
15	 * The password below is now a fixed constant, which is only safe because
16	 * `readConfig()` refuses to run against anything but a loopback address — see
17	 * the guard there before relaxing it.
18	 */
19	import { createClient, type SupabaseClient } from '@supabase/supabase-js';
20	
21	// ---- Identifiers (the only things that mark a row as "demo") ----------------
22	
23	export const FAMILY_NAME = 'Sample Family (DEMO)';
24	export const OWNER_EMAIL = 'sample.parent@example.com';
25	export const MEMBER_EMAIL = 'sample.partner@example.com';
26	export const DEMO_EMAILS = [OWNER_EMAIL, MEMBER_EMAIL];
27	
28	/**
29	 * Shared by both demo users. Fixed (not generated) so local tooling can log in
30	 * unattended — see src/lib/dev. Satisfies the app's own policy: 16+ chars, with
31	 * one each of upper/lower/digit/special. Safe to check in *only* because this
32	 * account can exist on a loopback stack and nowhere else.
33	 */
34	export const DEMO_PASSWORD = 'DemoFamily-2026!local';
35	
36	// ---- Environment / client ---------------------------------------------------
37	
38	export type DemoConfig = { url: string; serviceRoleKey: string };
39	
40	/** Loopback hosts the demo seed is allowed to touch. */
41	const LOCAL_HOSTS = ['127.0.0.1', 'localhost', '[::1]', '::1'];
42	
43	/**
44	 * Read + validate the required environment. Hard-fails with a clear message
45	 * rather than half-running against the wrong target.
46	 */
47	export function readConfig(): DemoConfig {
48		const url = process.env.PUBLIC_SUPABASE_URL;
49		const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
50	
51		const missing: string[] = [];
52		if (!url) missing.push('PUBLIC_SUPABASE_URL');
53		if (!serviceRoleKey) missing.push('SUPABASE_SERVICE_ROLE_KEY');
54		if (missing.length > 0) {
55			throw new Error(
56				`Missing required env var(s): ${missing.join(', ')}.\n` +
57					'The demo scripts inject these themselves — run:  npm run seed:demo'
58			);
59		}
60	
61		// The demo password is a checked-in constant, so "don't seed production" has
62		// to be an impossibility rather than a convention. Refuse anything that is
63		// not the local stack, and fail *before* the service-role client is built.
64		const host = new URL(url!).hostname;
65		if (!LOCAL_HOSTS.includes(host)) {
66			throw new Error(
67				`Refusing to run against a non-local target: ${host}.\n` +
68					'Demo data is local-only — the demo users share a fixed, checked-in password,\n' +
69					'so seeding a remote project would plant a known credential in it.\n' +
70					'Start the local stack with `npm run db:up` and re-run.'
71			);
72		}
73	
74		return { url: url!, serviceRoleKey: serviceRoleKey! };
75	}
76	
77	export function createAdminClient(config: DemoConfig): SupabaseClient {
78		return createClient(config.url, config.serviceRoleKey, {
79			auth: { autoRefreshToken: false, persistSession: false }
80		});
81	}
82	
83	/** Echo the target host so an accidental run against the wrong project is visible. */
84	export function targetHost(url: string): string {
85		try {
86			return new URL(url).host;
87		} catch {
88			return url;
89		}
90	}
91	
92	// ---- Teardown ---------------------------------------------------------------
93	
94	export type TeardownSummary = { usersDeleted: number; familiesDeleted: number };
95	
96	/** Find the demo auth users by email (paginates the admin user list). */
97	async function findDemoUserIds(admin: SupabaseClient): Promise<string[]> {
98		const ids: string[] = [];
99		const perPage = 1000;
100		for (let page = 1; ; page++) {
101			const { data, error } = await admin.auth.admin.listUsers({ page, perPage });
102			if (error) throw new Error(`listUsers failed: ${error.message}`);
103			for (const user of data.users) {
104				if (user.email && DEMO_EMAILS.includes(user.email)) ids.push(user.id);
105			}
106			if (data.users.length < perPage) break;
107		}
108		return ids;
109	}
110	
111	/**
112	 * Delete every demo artifact. Scoped strictly to the demo emails and the demo
113	 * family name, so it cannot touch real data.
114	 *
115	 * Deleting the auth users cascades their receipts + expense_categories +
116	 * family memberships. Deleting the family cascades its transactions, categories,
117	 * category_groups and importance_areas. Doing both leaves nothing behind.
118	 *
119	 * **The order matters — users first, then the family.** `receipts.family_id` is
120	 * ON DELETE SET NULL, not CASCADE; receipts only cascade via `receipts.user_id`.
121	 * Delete the family first and the demo receipts survive with a nulled family_id,
122	 * invisible to any name-scoped cleanup and permanently unattributable.
123	 */
124	export async function teardownDemo(admin: SupabaseClient): Promise<TeardownSummary> {
125		const userIds = await findDemoUserIds(admin);
126		for (const id of userIds) {
127			const { error } = await admin.auth.admin.deleteUser(id);
128			if (error) throw new Error(`deleteUser(${id}) failed: ${error.message}`);
129		}
130	
131		const { data: families, error: famErr } = await admin
132			.from('families')
133			.delete()
134			.eq('name', FAMILY_NAME)
135			.select('id');
136		if (famErr) throw new Error(`delete families failed: ${famErr.message}`);
137	
138		return { usersDeleted: userIds.length, familiesDeleted: families?.length ?? 0 };
139	}
