270			const params = clearDateFilterParams($page.url.searchParams);
271			goto(resolve(`/transactions?${params.toString()}`), {
272				replaceState: true,
273				keepFocus: true
274			});
275	
276			// Clear local filters
277			tempFilterVendor = '';
278			tempFilterAmountMin = '';
279			tempFilterAmountMax = '';
280			tempFilterCreditCardType = 'all'; // #{#tcf1a}
281			filterVendor = '';
282			filterAmountMin = '';
283			filterAmountMax = '';
