{
	"extends": "./.svelte-kit/tsconfig.json",
	"compilerOptions": {
		"allowJs": true,
		// scripts/demo/*.ts run under `tsx` as Node ESM, which requires explicit file
		// extensions, so they import each other as "./common.ts". Type-checking them means
		// permitting that specifier. Safe here because the generated config sets noEmit
		// (this option is only rejected when tsc actually emits JS), and it only permits
		// the extension — nothing in src/ is obliged to use it.
		"allowImportingTsExtensions": true,
		"checkJs": true,
		"esModuleInterop": true,
		"forceConsistentCasingInFileNames": true,
		"resolveJsonModule": true,
		"skipLibCheck": true,
		"sourceMap": true,
		"strict": true,
		"moduleResolution": "bundler"
	},
	// Path aliases are handled by https://svelte.dev/docs/kit/configuration#alias
	// except $lib which is handled by https://svelte.dev/docs/kit/configuration#files
	//
	// `include` does NOT merge with the extended config — it replaces it wholesale — so this
	// list restates every entry from .svelte-kit/tsconfig.json (rewritten relative to the repo
	// root) and then adds ours. Regenerating .svelte-kit does not update this; if SvelteKit ever
	// adds an entry there, add it here too. `exclude` is not restated, so it is inherited.
	//
	// scripts/ and e2e/ are the additions: the generated config covers only src/, test/, tests/
	// and vite.config.*, so the demo-seed scripts and the Playwright suite were never type-checked.
	// supabase/functions/ stays out on purpose — it is Deno, verified with `deno check`.
	"include": [
		".svelte-kit/ambient.d.ts",
		".svelte-kit/env.d.ts",
		".svelte-kit/non-ambient.d.ts",
		".svelte-kit/types/**/$types.d.ts",
		"vite.config.js",
		"vite.config.ts",
		"src/**/*.js",
		"src/**/*.ts",
		"src/**/*.svelte",
		"test/**/*.js",
		"test/**/*.ts",
		"test/**/*.svelte",
		"tests/**/*.js",
		"tests/**/*.ts",
		"tests/**/*.svelte",
		"scripts/**/*.ts",
		"e2e/**/*.ts"
	]
}

