/**
 * The demo family's identity — the only things that mark a row as "demo".
 *
 * Split out of `common.ts` because the browser needs it too: the dev-only
 * auto-login in `src/lib/dev/autoLogin.ts` signs in as the demo owner, and it
 * must not drag the service-role client (or `process.env`) into the client
 * bundle to do it. **Keep this module dependency-free** so importing it from
 * the app costs nothing.
 *
 * See docs/demo-seed.md.
 */

export const FAMILY_NAME = 'Sample Family (DEMO)';
export const OWNER_EMAIL = 'sample.parent@example.com';
export const MEMBER_EMAIL = 'sample.partner@example.com';
export const DEMO_EMAILS = [OWNER_EMAIL, MEMBER_EMAIL];

/**
 * Shared by both demo users. Fixed (not generated) so local tooling can log in
 * unattended — see `src/lib/dev/autoLogin.ts`. Satisfies the app's own policy:
 * 16+ chars, with one each of upper/lower/digit/special. Safe to check in
 * *only* because this account can exist on a loopback stack and nowhere else —
 * `readConfig()` in `common.ts` refuses any other target, and the auto-login
 * makes the same check before it sends the password anywhere.
 */
export const DEMO_PASSWORD = 'DemoFamily-2026!local';

/** Hosts the demo credential is allowed to reach. Loopback only, deliberately. */
export const LOCAL_HOSTS = ['127.0.0.1', 'localhost', '[::1]', '::1'];

/** True when `url` points at the local stack. A malformed URL is not local. */
export function isLocalSupabaseUrl(url: string): boolean {
	try {
		return LOCAL_HOSTS.includes(new URL(url).hostname);
	} catch {
		return false;
	}
}

