/**
 * #{#bmb1a} Dev-only auto-login against the local stack.
 *
 * Exists for tooling that has no way to authenticate itself. Bombadil (the
 * property-based UI explorer — see docs/plans/2026-07-26-bombadil-property-testing-spike.md)
 * has no `--storage-state`, no cookie flag and no login helper, and our session
 * lives in localStorage rather than a header, so `--header` cannot help either.
 * Rather than add a no-session code path just for the test tool, we establish a
 * *real* Supabase session at boot: auth and RLS stay entirely intact.
 *
 * **Two independent gates, for two different reasons.**
 *
 * - `import.meta.env.DEV` is what removes the credential from the production
 *   bundle. Vite substitutes `false`, the early return becomes unconditional,
 *   and Rollup drops everything below it — including the imported password
 *   string. A runtime-only check would still *ship* the password.
 * - The loopback check on `PUBLIC_SUPABASE_URL` is what stops `npm run dev:remote`
 *   — which points at production and is still DEV — from firing known demo
 *   credentials at it.
 *
 * `npm run test:e2e` is unaffected: it runs `vite build && vite preview`, so DEV
 * is false and none of this is in that bundle.
 */
import { PUBLIC_SUPABASE_URL } from '$env/static/public';
import { supabase } from '$lib/supabaseClient';
import { DEMO_PASSWORD, OWNER_EMAIL, isLocalSupabaseUrl } from '../../../scripts/demo/credentials.ts';

/**
 * Pages where being logged out is the whole point. Skipping them means a human
 * developer can still reach the login screen locally, and — more importantly —
 * that `logout()`'s redirect to `/login` is not immediately undone. Losing a
 * session stays visible instead of being silently papered over.
 */
const AUTH_ROUTES = ['/login', '/forgot-password', '/reset-password'];

/**
 * Sign in as the demo owner if nobody is signed in yet. Resolves once the
 * session exists (or once we've decided not to create one), so callers can
 * await it before deciding whether the user is authenticated.
 *
 * Never throws: a failure here must not take the app down. An unseeded database
 * is the common cause, so say so.
 */
export async function autoLoginForDev(): Promise<void> {
	if (!import.meta.env.DEV) return;
	if (!isLocalSupabaseUrl(PUBLIC_SUPABASE_URL)) return;
	if (AUTH_ROUTES.includes(window.location.pathname)) return;

	const { data } = await supabase.auth.getSession();
	if (data.session) return;

	const { error } = await supabase.auth.signInWithPassword({
		email: OWNER_EMAIL,
		password: DEMO_PASSWORD
	});

	if (error) {
		console.warn(
			`[dev auto-login] Could not sign in as ${OWNER_EMAIL}: ${error.message}\n` +
				'Seed the local stack with `npm run seed:demo` (or `npm run db:fresh`).'
		);
	}
}

