/**
 * Bombadil specification for the Transactions page (#{#bmb1a}).
 *
 * Run with `npm run bombadil` (see docs/plans/2026-07-26-bombadil-property-testing-spike.md).
 * Requires the local stack seeded and `npm run dev` running — the dev-only
 * auto-login in `src/lib/dev/autoLogin.ts` supplies the session, because
 * Bombadil has no authentication support of its own.
 *
 * ## Why this file is hand-written rather than `export *`-ing the defaults
 *
 * `<ORIGIN>` is an *origin* boundary, not a page boundary: passing
 * `http://localhost:5173/transactions` does nothing to stop Bombadil wandering
 * into `/expenses` or `/profile`. Single-page confinement has to come from the
 * specification, so we re-export the default *properties* only and enumerate
 * every action target ourselves. `pageIsAlwaysTransactions` below is the
 * tripwire that turns an escape into a loud violation instead of silent scope
 * creep.
 *
 * ## What is deliberately NOT clickable, and why
 *
 * - **The whole `<header>`.** It holds Logout. One click and the rest of the run
 *   explores `/login`. Every target set is rooted at `<main>`.
 * - **The import card.** Its file input opens a native OS file chooser, which
 *   nothing in the page can dismiss — the run would simply hang.
 * - **Row `Delete` and `Delete Selected`.** Two reasons. They call `confirm()`,
 *   a modal browser dialog outside the DOM that the action vocabulary cannot
 *   answer; and they destroy the seeded rows the run needs, which also breaks
 *   `--reproduce` (it replays faithfully only from an identical start state).
 * - **`Back` / `Forward` / `Reload`.** All three leave or reset the page under
 *   test for no exploratory gain.
 * - **`Tab`.** Focus traversal walks straight out of `<main>` and into the
 *   header's Logout button, where a subsequent `Enter` ends the run.
 *
 * Receipt OCR is unreachable from here — the page never uploads a receipt, and
 * the only browser-side Mistral touchpoint is `ReceiptService`'s
 * `POST /api/ocr/extract`. Belt and braces, `npm run dev` sets no
 * `MISTRAL_API_KEY`, so the endpoint 500s if it is ever reached and the free
 * `noHttpErrorCodes` property fires.
 */
import { always, from, not, now } from '@antithesishq/bombadil';
import type { Cell } from '@antithesishq/bombadil';
import { actions, extract, weighted } from '@antithesishq/bombadil/browser';
import type { Action, State } from '@antithesishq/bombadil/browser';

/** The four free properties: no uncaught exceptions, rejections, console errors or 4xx/5xx. */
export {
	noConsoleErrors,
	noHttpErrorCodes,
	noUncaughtExceptions,
	noUnhandledPromiseRejections
} from '@antithesishq/bombadil/browser/defaults';

const PAGE_PATH = '/transactions';

// ---------------------------------------------------------------------------
// DOM helpers
//
// Extractors may only return JSON, so nothing here hands back an Element — the
// element hunting happens inside the extractor and only names and coordinates
// come out.
// ---------------------------------------------------------------------------

type Point = { x: number; y: number };
/** A thing worth clicking: a stable label for the trace plus where to click it. */
type Target = { name: string; content: string; point: Point };

function textOf(element: Element): string {
	return (element.textContent ?? '').replace(/\s+/g, ' ').trim();
}

/**
 * Where to click `element`, or null if clicking it would be meaningless:
 * zero-sized, hidden, disabled, or scrolled outside the viewport. Bombadil
 * dispatches at a coordinate, so an off-screen target would land on whatever
 * happens to be there instead.
 */
function clickPoint(state: State, element: Element): Point | null {
	if ('disabled' in element && element.disabled === true) return null;

	const rect = element.getBoundingClientRect();
	if (rect.width <= 0 || rect.height <= 0) return null;
	if (state.window.getComputedStyle(element).visibility === 'hidden') return null;

	const point = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
	const withinViewport =
		point.x >= 0 &&
		point.y >= 0 &&
		point.x < state.window.innerWidth &&
		point.y < state.window.innerHeight;

	return withinViewport ? point : null;
}

/** The page body. Everything is scoped to it so the header is unreachable. */
function main(state: State): Element | null {
	return state.document.querySelector('main');
}

/**
 * The Edit Transaction dialog's panel, when it is open. Found by its heading
 * rather than its utility classes, which are Tailwind noise and change freely.
 */
function editDialog(root: Element): Element | null {
	for (const heading of root.querySelectorAll('h3')) {
		if (textOf(heading) === 'Edit Transaction') return heading.parentElement;
	}
	return null;
}

/**
 * Register an extractor yielding click targets.
 *
 * `where` decides which elements are in play. Because the dialog is a modal
 * overlay, `insideDialog` splits the two worlds: dialog targets only exist
 * while it is open, page targets only while it is closed. Without that, most
 * generated clicks while the dialog is open would land on the backdrop.
 */
function targets(
	label: string,
	insideDialog: boolean,
	where: (root: Element) => Iterable<Element>
): Cell<Target[]> {
	return extract((state) => {
		const body = main(state);
		if (!body) return [];

		const dialog = editDialog(body);
		if (insideDialog !== (dialog !== null)) return [];
		const root = insideDialog ? dialog! : body;

		const found: Target[] = [];
		for (const element of where(root)) {
			const point = clickPoint(state, element);
			if (point) found.push({ name: `${label}[${found.length}]`, content: textOf(element), point });
		}
		return found;
	});
}

function queryAll(root: Element, selector: string): Element[] {
	return Array.from(root.querySelectorAll(selector));
}

/** Buttons whose visible label starts with `prefix` — for controls with no id or aria-label. */
function buttonsLabelled(root: Element, prefix: string): Element[] {
	return queryAll(root, 'button').filter((b) => textOf(b).startsWith(prefix));
}

// ---------------------------------------------------------------------------
// Action targets
// ---------------------------------------------------------------------------

const filterTextInputs = targets('filter-input', false, (root) =>
	queryAll(root, '#tx-filter-vendor, #tx-filter-amount-min, #tx-filter-amount-max')
);

// A native <select>. Clicking opens Chrome's own popup, which lives outside the
// DOM; the arrow/Enter/Escape keys in `keyPresses` are what drive and dismiss it.
const filterCardType = targets('filter-cardtype', false, (root) =>
	queryAll(root, '#tx-filter-cardtype')
);

const filterButtons = targets('filter-button', false, (root) =>
	queryAll(root, 'button[aria-label="Apply filters"], button[aria-label="Clear filters"]')
);

/** The "Show excluded" toggle — no id, so it is found by its label text. */
const showExcludedToggle = targets('show-excluded', false, (root) =>
	queryAll(root, 'input[type="checkbox"]').filter((box) =>
		textOf(box.parentElement ?? box).startsWith('Show excluded')
	)
);

// flowbite's Datepicker: a trigger button, then a `role="dialog"` calendar whose
// days are gridcells. Driving it through those roles beats typing into the input.
const datepickerTriggers = targets('datepicker', false, (root) =>
	queryAll(root, 'button[aria-label="Open date picker"], button[aria-label="Close date picker"]')
);

const calendarControls = targets('calendar', false, (root) => [
	...queryAll(root, '[role="dialog"][aria-label="Calendar"] [role="gridcell"]:not([aria-disabled="true"])'),
	...queryAll(
		root,
		'[role="dialog"][aria-label="Calendar"] button[aria-label="Next month"], [role="dialog"][aria-label="Calendar"] button[aria-label="Previous month"]'
	)
]);

const selectionCheckboxes = targets('select', false, (root) =>
	queryAll(root, 'input[aria-label="Select all"], input[aria-label="Select row"]')
);

const clearSelection = targets('clear-selection', false, (root) =>
	buttonsLabelled(root, 'Clear Selection')
);

const sortHeaders = targets('sort', false, (root) => queryAll(root, 'th[role="columnheader"]'));

/**
 * Cells that open a row for editing. The first cell holds the select checkbox
 * and the last is the interactive actions cell; neither opens the row.
 */
