	let bothDisabled = true;
	let found = 0;

	for (const button of body.querySelectorAll('button')) {
		const text = textOf(button);
		if (text.startsWith('Delete Selected')) {
			const matched = /\((\d+)\)/.exec(text);
			count = matched ? Number(matched[1]) : null;
		} else if (!text.startsWith('Clear Selection')) {
			continue;
		}
		found += 1;
		if (!(button as HTMLButtonElement).disabled) bothDisabled = false;
	}

	return found === 2 && count !== null ? { count, bothDisabled } : null;
});

export const selectionButtonsMatchTheSelection = always(() => {
	const buttons = selectionButtons.current;
	if (buttons === null) return true;

	const ticked = rows.current.filter((row) => row.checked).length;
	return buttons.count >= ticked && buttons.bothDisabled === (buttons.count === 0);
});

/**
 * The edit dialog always offers a way out. It has no backdrop-click or Escape
 * handler, so if Cancel ever went missing the page would be stuck — and so
 * would the run.
 */
const dialogIsEscapable = extract((state) => {
	const body = main(state);
	if (!body) return true;

	const dialog = editDialog(body);
	return dialog === null || buttonsLabelled(dialog, 'Cancel').length > 0;
});

export const editDialogCanAlwaysBeClosed = always(() => dialogIsEscapable.current);

/**
 * The list is never *silently* empty: an empty table always says why, either
 * "No transactions yet" or the filtered-empty state. Guards against a filter
 * bug that wipes the table and leaves a blank slab behind.
 */
const emptyStateExplained = extract((state) => {
	const body = main(state);
	if (!body) return true;
	if (queryAll(body, 'tbody tr[role="button"]').length > 0) return true;

	const text = textOf(body);
	return text.includes('No transactions yet') || text.includes('No transactions match');
});

export const anEmptyTableExplainsItself = always(
	now(() => rows.current.length > 0).or(() => emptyStateExplained.current)
);

/** `Importing...` should never be reachable: nothing here touches the file input. */
const importInFlight = extract((state) => {
	const body = main(state);
	return body !== null && textOf(body).includes('Importing...');
});

export const importIsNeverTriggered = always(not(() => importInFlight.current));

