1	/**
2	 * Bombadil specification for the Transactions page (#{#bmb1a}).
3	 *
4	 * Run with `npm run bombadil` (see docs/plans/2026-07-26-bombadil-property-testing-spike.md).
5	 * Requires the local stack seeded and `npm run dev` running — the dev-only
6	 * auto-login in `src/lib/dev/autoLogin.ts` supplies the session, because
7	 * Bombadil has no authentication support of its own.
8	 *
9	 * ## Why this file is hand-written rather than `export *`-ing the defaults
10	 *
11	 * `<ORIGIN>` is an *origin* boundary, not a page boundary: passing
12	 * `http://localhost:5173/transactions` does nothing to stop Bombadil wandering
13	 * into `/expenses` or `/profile`. Single-page confinement has to come from the
14	 * specification, so we re-export the default *properties* only and enumerate
15	 * every action target ourselves. `pageIsAlwaysTransactions` below is the
16	 * tripwire that turns an escape into a loud violation instead of silent scope
17	 * creep.
18	 *
19	 * ## What is deliberately NOT clickable, and why
20	 *
21	 * - **The whole `<header>`.** It holds Logout. One click and the rest of the run
22	 *   explores `/login`. Every target set is rooted at `<main>`.
23	 * - **The import card.** Its file input opens a native OS file chooser, which
24	 *   nothing in the page can dismiss — the run would simply hang.
25	 * - **Row `Delete` and `Delete Selected`.** Two reasons. They call `confirm()`,
26	 *   a modal browser dialog outside the DOM that the action vocabulary cannot
27	 *   answer; and they destroy the seeded rows the run needs, which also breaks
28	 *   `--reproduce` (it replays faithfully only from an identical start state).
29	 * - **`Back` / `Forward` / `Reload`.** All three leave or reset the page under
30	 *   test for no exploratory gain.
31	 * - **`Tab`.** Focus traversal walks straight out of `<main>` and into the
32	 *   header's Logout button, where a subsequent `Enter` ends the run.
33	 *
34	 * Receipt OCR is unreachable from here — the page never uploads a receipt, and
35	 * the only browser-side Mistral touchpoint is `ReceiptService`'s
36	 * `POST /api/ocr/extract`. Belt and braces, `npm run dev` sets no
37	 * `MISTRAL_API_KEY`, so the endpoint 500s if it is ever reached and the free
38	 * `noHttpErrorCodes` property fires.
39	 */
40	import { always, from, not } from '@antithesishq/bombadil';
41	import type { Cell } from '@antithesishq/bombadil';
42	import { actions, extract, weighted } from '@antithesishq/bombadil/browser';
43	import type { Action, State } from '@antithesishq/bombadil/browser';
44	
45	/** The four free properties: no uncaught exceptions, rejections, console errors or 4xx/5xx. */
46	export {
47		noConsoleErrors,
48		noHttpErrorCodes,
49		noUncaughtExceptions,
50		noUnhandledPromiseRejections
51	} from '@antithesishq/bombadil/browser/defaults';
52	
53	const PAGE_PATH = '/transactions';
54	
55	// ---------------------------------------------------------------------------
56	// DOM helpers
57	//
58	// Extractors may only return JSON, so nothing here hands back an Element — the
59	// element hunting happens inside the extractor and only names and coordinates
60	// come out.
61	// ---------------------------------------------------------------------------
62	
63	type Point = { x: number; y: number };
64	/** A thing worth clicking: a stable label for the trace plus where to click it. */
65	type Target = { name: string; content: string; point: Point };
66	
67	function textOf(element: Element): string {
68		return (element.textContent ?? '').replace(/\s+/g, ' ').trim();
69	}
70	
71	/**
72	 * Where to click `element`, or null if clicking it would be meaningless:
73	 * zero-sized, hidden, disabled, or scrolled outside the viewport. Bombadil
74	 * dispatches at a coordinate, so an off-screen target would land on whatever
75	 * happens to be there instead.
76	 */
77	function clickPoint(state: State, element: Element): Point | null {
78		if ('disabled' in element && element.disabled === true) return null;
79	
80		const rect = element.getBoundingClientRect();
81		if (rect.width <= 0 || rect.height <= 0) return null;
82		if (state.window.getComputedStyle(element).visibility === 'hidden') return null;
83	
84		const point = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
85		const withinViewport =
86			point.x >= 0 &&
87			point.y >= 0 &&
88			point.x < state.window.innerWidth &&
89			point.y < state.window.innerHeight;
90	
91		return withinViewport ? point : null;
92	}
93	
94	/** The page body. Everything is scoped to it so the header is unreachable. */
95	function main(state: State): Element | null {
96		return state.document.querySelector('main');
97	}
98	
99	/**
100	 * The Edit Transaction dialog's panel, when it is open. Found by its heading
101	 * rather than its utility classes, which are Tailwind noise and change freely.
102	 */
103	function editDialog(root: Element): Element | null {
104		for (const heading of root.querySelectorAll('h3')) {
105			if (textOf(heading) === 'Edit Transaction') return heading.parentElement;
106		}
107		return null;
108	}
109	
110	/**
111	 * Register an extractor yielding click targets.
112	 *
113	 * `where` decides which elements are in play. Because the dialog is a modal
114	 * overlay, `insideDialog` splits the two worlds: dialog targets only exist
115	 * while it is open, page targets only while it is closed. Without that, most
116	 * generated clicks while the dialog is open would land on the backdrop.
117	 */
118	function targets(
119		label: string,
120		insideDialog: boolean,
121		where: (root: Element) => Iterable<Element>
122	): Cell<Target[]> {
123		return extract((state) => {
124			const body = main(state);
125			if (!body) return [];
126	
127			const dialog = editDialog(body);
128			if (insideDialog !== (dialog !== null)) return [];
129			const root = insideDialog ? dialog! : body;
130	
131			const found: Target[] = [];
132			for (const element of where(root)) {
133				const point = clickPoint(state, element);
134				if (point) found.push({ name: `${label}[${found.length}]`, content: textOf(element), point });
135			}
136			return found;
137		});
138	}
139	
140	function queryAll(root: Element, selector: string): Element[] {
141		return Array.from(root.querySelectorAll(selector));
142	}
143	
144	/** Buttons whose visible label starts with `prefix` — for controls with no id or aria-label. */
145	function buttonsLabelled(root: Element, prefix: string): Element[] {
146		return queryAll(root, 'button').filter((b) => textOf(b).startsWith(prefix));
147	}
148	
149	// ---------------------------------------------------------------------------
150	// Action targets
151	// ---------------------------------------------------------------------------
152	
153	const filterTextInputs = targets('filter-input', false, (root) =>
154		queryAll(root, '#tx-filter-vendor, #tx-filter-amount-min, #tx-filter-amount-max')
155	);
156	
157	// A native <select>. Clicking opens Chrome's own popup, which lives outside the
158	// DOM; the arrow/Enter/Escape keys in `keyPresses` are what drive and dismiss it.
159	const filterCardType = targets('filter-cardtype', false, (root) =>
160		queryAll(root, '#tx-filter-cardtype')
161	);
162	
163	const filterButtons = targets('filter-button', false, (root) =>
164		queryAll(root, 'button[aria-label="Apply filters"], button[aria-label="Clear filters"]')
