166	
167	/** The "Show excluded" toggle — no id, so it is found by its label text. */
168	const showExcludedToggle = targets('show-excluded', false, (root) =>
169		queryAll(root, 'input[type="checkbox"]').filter((box) =>
170			textOf(box.parentElement ?? box).startsWith('Show excluded')
171		)
172	);
173	
174	// flowbite's Datepicker: a trigger button, then a `role="dialog"` calendar whose
175	// days are gridcells. Driving it through those roles beats typing into the input.
176	const datepickerTriggers = targets('datepicker', false, (root) =>
