	const body = main(state);
	if (!body) return found;

	const collect = (group: Group, elements: Iterable<Element>) => {
		const list = found[group];
		for (const element of elements) {
			const point = clickPoint(state, element);
			if (point) list.push({ name: `${group}[${list.length}]`, content: textOf(element), point });
