	collect('dismiss', buttonsLabelled(body, 'Dismiss'));

	// Row-level controls. Reject the row by its own rectangle first: with ~100
	// rows and only ~15 on screen, measuring every cell of every row is most of
	// the extractor's cost for nothing.
	const selectAll = body.querySelector('input[aria-label="Select all"]');
