	[8, clicks('filter-button')],
	[6, clicks('filter-input')],
	[6, typing],
	[5, clicks('select')],
	[5, clicks('sort')],
	[4, clicks('datepicker')],
	[4, clicks('calendar')],
	[3, clicks('show-excluded')],
	[3, clicks('filter-cardtype')],
	[3, keyPresses],
	[3, clicks('row')],
	[3, scrolling],
	[2, clicks('clear-selection')],
	[2, clicks('dialog-field')],
	[2, clicks('dialog-calendar')],
	[2, clicks('dialog-button')],
	[1, clicks('exclude')],
	[1, clicks('dismiss')],
	[1, 'Wait']
]);

