/**
 * The scope tripwire. `<ORIGIN>` cannot enforce a single page, so this does:
 * anything that navigates away — a stray header click, a session loss bouncing
 * us to `/login` — surfaces as a violation rather than as a run that quietly
 * spent its budget somewhere else.
 */
export const pageIsAlwaysTransactions = always(() => path.current === PAGE_PATH);

/**
 * Every data row as the DOM presents it, plus whether the table exists at all.
 * `always` starts at the very first state, where the layout is still showing
 * "Loading…" while it checks the session — `settled` is what stops the
 * properties below judging a page that has not rendered yet.
 */
