 * The header checkbox is checked exactly when every visible row is selected, and
 * indeterminate exactly when some but not all are — the contract `isAllSelected`
 * / `isIndeterminate` are supposed to implement, checked against the rendering
 * rather than against a re-implementation of the same arithmetic.
 */
export const selectAllReflectsTheRows = always(() => {
	const box = selectAllBox.current;
	if (box === null) return true;

	const rows = table.current.rows;
	const selected = rows.filter((row) => row.checked).length;
	const all = rows.length > 0 && selected === rows.length;

	return box.checked === all && box.indeterminate === (selected > 0 && !all);
});

/**
 * `Delete Selected (N)` and `Clear Selection`, and whether both are disabled.
 */
const selectionButtons = extract((state) => {
	const body = main(state);
	if (!body) return null;

	let count: number | null = null;
	let bothDisabled = true;
	let found = 0;

	for (const button of body.querySelectorAll('button')) {
		const text = textOf(button);
		if (text.startsWith('Delete Selected')) {
			const matched = /\((\d+)\)/.exec(text);
			count = matched ? Number(matched[1]) : null;
		} else if (!text.startsWith('Clear Selection')) {
			continue;
		}
		found += 1;
		if (!(button as HTMLButtonElement).disabled) bothDisabled = false;
	}

