	collect('filter-input', queryAll(body, '#tx-filter-vendor, #tx-filter-amount-min, #tx-filter-amount-max'));

	// A native <select>. Clicking opens Chrome's own popup, which lives outside
	// the DOM; the arrow/Enter/Escape keys in `keyPresses` are what drive it.
	collect('filter-cardtype', queryAll(body, '#tx-filter-cardtype'));

	collect(
		'filter-button',
		queryAll(body, 'button[aria-label="Apply filters"], button[aria-label="Clear filters"]')
	);

	// The "Show excluded" toggle has no id, so it is found by its label text.
	collect(
		'show-excluded',
		queryAll(body, 'input[type="checkbox"]').filter((box) =>
			textOf(box.parentElement ?? box).startsWith('Show excluded')
		)
	);

	// flowbite's Datepicker: a trigger button, then a `role="dialog"` calendar
	// whose days are gridcells. Driving it through those roles beats typing.
	collect(
		'datepicker',
		queryAll(body, 'button[aria-label="Open date picker"], button[aria-label="Close date picker"]')
	);
	collect('calendar', [
		...queryAll(body, `${CALENDAR} [role="gridcell"]:not([aria-disabled="true"])`),
		...queryAll(
			body,
			`${CALENDAR} button[aria-label="Next month"], ${CALENDAR} button[aria-label="Previous month"]`
		)
	]);

	collect('clear-selection', buttonsLabelled(body, 'Clear Selection'));
	collect('sort', queryAll(body, 'th[role="columnheader"]'));
	collect('dismiss', buttonsLabelled(body, 'Dismiss'));

	// Row-level controls. Reject the row by its own rectangle first: with ~100
	// rows and only ~15 on screen, measuring every cell of every row is most of
	// the extractor's cost for nothing.
	const selectAll = body.querySelector('input[aria-label="Select all"]');
	const checkboxes: Element[] = selectAll ? [selectAll] : [];
	const cells: Element[] = [];
	const toggles: Element[] = [];

	for (const row of body.querySelectorAll(ROW_SELECTOR)) {
		const rect = row.getBoundingClientRect();
		if (rect.bottom <= 0 || rect.top >= state.window.innerHeight) continue;

		const columns = Array.from(row.children);
		// The first column holds the select checkbox and the last is the
		// interactive actions cell; neither opens the row for editing.
		cells.push(...columns.slice(1, Math.max(1, columns.length - 1)));

		const box = row.querySelector('input[aria-label="Select row"]');
		if (box) checkboxes.push(box);

		toggles.push(
			...queryAll(
				row,
				'button[aria-label="Exclude transaction"], button[aria-label="Include transaction"]'
			)
		);
	}

	collect('select', checkboxes);
	collect('row', cells);
	collect('exclude', toggles);

	return found;
});

// ---------------------------------------------------------------------------
// Action generators
// ---------------------------------------------------------------------------

function clicks(group: Group) {
	return actions(() => (pageTargets.current[group] ?? []).map((target): Action => ({ Click: target })));
}

/**
 * Text typed into whatever a preceding click focused. A mix of vendor fragments
 * that exist in the demo data (so filters actually match something), amounts,
 * and junk that should match nothing.
 */
const TEXT = from(['Costco', 'cost', 'amazon', 'ZZZ-no-such-vendor', '12', '19.99', '-5', '0', ' ']);

const typing = actions((): Action[] => [{ TypeText: { text: TEXT.generate(), delayMillis: 10 } }]);

// Backspace, Enter, Escape and the arrows. No Tab: it walks focus out of <main>
// and into the header's Logout button.
const KEYCODE = from([8, 13, 27, 37, 38, 39, 40]);

const keyPresses = actions((): Action[] => [{ PressKey: { code: KEYCODE.generate() } }]);

const scrollOrigin = extract((state) => ({
	x: Math.floor(state.window.innerWidth / 2),
	y: Math.floor(state.window.innerHeight / 2)
}));

const scrolling = weighted([
	[1, actions((): Action[] => [{ ScrollDown: { origin: scrollOrigin.current, distance: 400 } }])],
	[1, actions((): Action[] => [{ ScrollUp: { origin: scrollOrigin.current, distance: 400 } }])]
]);

/**
 * The one action generator. Weights favour the cheap, reversible controls
 * (filters, selection, sorting) over the ones that write to the database
 * (Exclude/Include, and Save in the edit dialog).
 */
export const transactionsPage = weighted([
	[8, clicks('filter-button')],
	[6, clicks('filter-input')],
	[6, typing],
	[5, clicks('select')],
	[5, clicks('sort')],
	[4, clicks('datepicker')],
	[4, clicks('calendar')],
	[3, clicks('show-excluded')],
	[3, clicks('filter-cardtype')],
	[3, keyPresses],
	[3, clicks('row')],
	[3, scrolling],
	[2, clicks('clear-selection')],
	[2, clicks('dialog-field')],
	[2, clicks('dialog-calendar')],
	[2, clicks('dialog-button')],
	[1, clicks('exclude')],
	[1, clicks('dismiss')],
	[1, 'Wait']
]);

// ---------------------------------------------------------------------------
// Properties
//
// These extractors read text and checkbox state only — no geometry — so they
// cost nothing beyond the DOM walk.
// ---------------------------------------------------------------------------

const path = extract((state) => state.window.location.pathname);

/**
 * The scope tripwire. `<ORIGIN>` cannot enforce a single page, so this does:
 * anything that navigates away — a stray header click, a session loss bouncing
 * us to `/login` — surfaces as a violation rather than as a run that quietly
 * spent its budget somewhere else.
 */
export const pageIsAlwaysTransactions = always(() => path.current === PAGE_PATH);

/**
 * Every data row as the DOM presents it, plus whether the table exists at all.
 * `always` starts at the very first state, where the layout is still showing
 * "Loading…" while it checks the session — `settled` is what stops the
 * properties below judging a page that has not rendered yet.
 */
const table = extract((state) => {
	const body = main(state);
	if (!body || !body.querySelector('tbody')) return { settled: false, rows: [], emptyState: '' };

	const rows = queryAll(body, ROW_SELECTOR).map((row) => {
		const columns = Array.from(row.children);
		const box = row.querySelector('input[aria-label="Select row"]');
		return {
			date: columns[1] ? textOf(columns[1]) : '',
			checked: box instanceof HTMLInputElement && box.checked
		};
	});

	const tbody = body.querySelector('tbody');
	return { settled: true, rows, emptyState: tbody ? textOf(tbody) : '' };
});

/** `Showing N of M transactions`, which the page renders only while a filter is active. */
const showingCounts = extract((state) => {
	const body = main(state);
	if (!body) return null;

	for (const span of body.querySelectorAll('span')) {
		const matched = /^Showing (\d+) of (\d+) transactions$/.exec(textOf(span));
		if (matched) return { shown: Number(matched[1]), total: Number(matched[2]) };
	}
	return null;
});

/**
 * The filtered count can never exceed the unfiltered one, and must agree with
 * what is actually on screen. A filter that drops rows without updating the
 * count (or vice versa) shows up here.
 */
export const rowCountMatchesTheShowingCounter = always(() => {
	const counts = showingCounts.current;
	return (
		counts === null || (counts.shown <= counts.total && counts.shown === table.current.rows.length)
	);
});

/** `Mar 1, 2026` (what `formatDate` renders) back to `2026-03-01`, for comparison with the URL. */
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

function toIsoDate(displayed: string): string | null {
	const matched = /^([A-Z][a-z]{2}) (\d{1,2}), (\d{4})$/.exec(displayed);
	if (!matched) return null;

	const month = MONTHS.indexOf(matched[1]);
	if (month === -1) return null;

	return `${matched[3]}-${String(month + 1).padStart(2, '0')}-${matched[2].padStart(2, '0')}`;
}

const urlDateRange = extract((state) => {
	const params = new URLSearchParams(state.window.location.search);
	return { from: params.get('dateFrom') ?? '', to: params.get('dateTo') ?? '' };
});

/**
 * The real filter-correctness property: the date range lives in the URL, so it
 * and the rows it is supposed to be filtering are both observable. Both bounds
 * are inclusive (`matchesDateRange`). ISO dates compare correctly as strings.
 */
export const noRowFallsOutsideTheDateFilter = always(() => {
	const range = urlDateRange.current;
	if (!range.from && !range.to) return true;

	return table.current.rows.every((row) => {
		const date = toIsoDate(row.date);
		if (date === null) return true; // an em-dash placeholder — nothing to check
		return (!range.from || date >= range.from) && (!range.to || date <= range.to);
	});
});

/** The header checkbox's tri-state, as rendered. */
const selectAllBox = extract((state) => {
	const box = main(state)?.querySelector('input[aria-label="Select all"]');
	if (!(box instanceof HTMLInputElement)) return null;
	return { checked: box.checked, indeterminate: box.indeterminate };
});

/**
 * The header checkbox is checked exactly when every visible row is selected, and
 * indeterminate exactly when some but not all are — the contract `isAllSelected`
 * / `isIndeterminate` are supposed to implement, checked against the rendering
 * rather than against a re-implementation of the same arithmetic.
 */
export const selectAllReflectsTheRows = always(() => {
	const box = selectAllBox.current;
	if (box === null) return true;

	const rows = table.current.rows;
	const selected = rows.filter((row) => row.checked).length;
	const all = rows.length > 0 && selected === rows.length;

	return box.checked === all && box.indeterminate === (selected > 0 && !all);
});

/**
 * `Delete Selected (N)` and `Clear Selection`, and whether both are disabled.
 */
const selectionButtons = extract((state) => {
	const body = main(state);
	if (!body) return null;

	let count: number | null = null;
	let bothDisabled = true;
	let found = 0;

	for (const button of body.querySelectorAll('button')) {
		const text = textOf(button);
		if (text.startsWith('Delete Selected')) {
			const matched = /\((\d+)\)/.exec(text);
			count = matched ? Number(matched[1]) : null;
		} else if (!text.startsWith('Clear Selection')) {
			continue;
		}
		found += 1;
		if (!(button as HTMLButtonElement).disabled) bothDisabled = false;
	}

	return found === 2 && count !== null ? { count, bothDisabled } : null;
});

/**
 * Both buttons are enabled exactly when the selection is non-empty, and N is
 * never smaller than the number of ticked rows on screen. Deliberately not an
 * equality: `toggleSelectAll` keeps rows selected after a filter hides them, so
 * N legitimately runs ahead of the DOM.
 */
export const selectionButtonsMatchTheSelection = always(() => {
	const buttons = selectionButtons.current;
	if (buttons === null) return true;

	const ticked = table.current.rows.filter((row) => row.checked).length;
	return buttons.count >= ticked && buttons.bothDisabled === (buttons.count === 0);
});

/**
 * The edit dialog always offers a way out. It has no backdrop-click or Escape
 * handler, so if Cancel ever went missing the page would be stuck — and so
 * would the run.
 */
const dialogIsEscapable = extract((state) => {
	const body = main(state);
	if (!body) return true;

	const dialog = editDialog(body);
	return dialog === null || buttonsLabelled(dialog, 'Cancel').length > 0;
});

export const editDialogCanAlwaysBeClosed = always(() => dialogIsEscapable.current);

/**
 * The list is never *silently* empty: an empty table always says why — either
 * "No transactions yet" (#{#ems1a}) or "No results found" (#{#ems1b}). Guards
 * against a filter bug that wipes the table and leaves a blank slab behind.
 */
export const anEmptyTableExplainsItself = always(() => {
	const { settled, rows, emptyState } = table.current;
	if (!settled || rows.length > 0) return true;

	return emptyState.includes('No transactions yet') || emptyState.includes('No results found');
});

/** `Importing...` should never be reachable: nothing here touches the file input. */
const importInFlight = extract((state) => {
	const body = main(state);
	if (!body) return false;

	const fileInput = body.querySelector('input[type="file"]');
	const label = fileInput?.closest('label');
	return label !== null && label !== undefined && textOf(label).includes('Importing...');
});

export const importIsNeverTriggered = always(not(() => importInFlight.current));

