/**
 * Where to click `element`, or null if a click there would not reach it:
 * disabled, zero-sized, scrolled out of the viewport, or covered by something.
 *
 * The hit test is the part that matters. Bombadil dispatches at a coordinate,
 * not at a node, so "in the viewport" is not the same as "clickable" — the
 * layout's `sticky top-0` header floats over the top ~53px of the scrolled
 * page. Without `elementFromPoint`, a row checkbox that had scrolled under the
 * header handed back a point that landed on a nav link, and the run left the
 * page entirely. (The `pageIsAlwaysTransactions` tripwire is what caught it.)
 * The same check keeps clicks off anything behind the datepicker popover or the
 * edit dialog's backdrop.
 */
function clickPoint(state: State, element: Element): Point | null {
	if ('disabled' in element && element.disabled === true) return null;

	const rect = element.getBoundingClientRect();
	if (rect.width <= 0 || rect.height <= 0) return null;

	const point = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
	const onScreen =
		point.x >= 0 &&
		point.y >= 0 &&
		point.x < state.window.innerWidth &&
		point.y < state.window.innerHeight;
	if (!onScreen) return null;

	const hit = state.document.elementFromPoint(point.x, point.y);
	return hit !== null && (hit === element || element.contains(hit)) ? point : null;
}

