import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render } from 'vitest-browser-svelte';
import {
	pageStore,
	supabaseMock,
	setRoute,
	setSession,
	setSessionPending,
	fakeSession,
	resetHarness
} from './harness/appMocks';

// Replace the SvelteKit page store and the Supabase singleton before the layout
// (imported transitively via LayoutHarness) mounts. See harness/appMocks.ts.
vi.mock('$app/stores', () => ({ page: pageStore }));
vi.mock('$lib/supabaseClient', () => ({ supabase: supabaseMock }));

import LayoutHarness from './harness/LayoutHarness.svelte';

/**
 * Behavior tests for +layout.svelte — the app-wide auth gate and header nav.
 *
 * Replaces two source-introspection specs that regex'd the layout source:
 * - auth-route-guard.spec.ts
 * - layout-navigation.spec.ts
 * These render the real layout and assert what a user actually sees for each
 * auth/route combination. Built on the route-render harness (harness/appMocks.ts).
 */
describe('+layout.svelte', () => {
	beforeEach(resetHarness);

	describe('auth gate', () => {
		it('renders the protected page content when signed in', async () => {
			setSession(fakeSession());
			setRoute('/expenses');

			const screen = render(LayoutHarness);

			await expect.element(screen.getByTestId('page-content')).toBeVisible();
		});

		it('shows the not-logged-in message instead of the page on a protected route when signed out', async () => {
			setSession(null);
			setRoute('/expenses');

			const screen = render(LayoutHarness);

			await expect.element(screen.getByText('You are not logged in.')).toBeVisible();
			await expect.element(screen.getByRole('link', { name: 'Go to login' })).toBeVisible();
			await expect.element(screen.getByTestId('page-content')).not.toBeInTheDocument();
		});

		it('renders page content on a public route even when signed out', async () => {
			// '/login' is in the layout's publicRoutes allow-list.
			setSession(null);
			setRoute('/login');

			const screen = render(LayoutHarness);

			await expect.element(screen.getByTestId('page-content')).toBeVisible();
			await expect.element(screen.getByText('You are not logged in.')).not.toBeInTheDocument();
		});

		it('shows the Loading placeholder before the session check resolves', async () => {
			// Protected route, getSession still pending → neither the page nor the
			// not-logged-in message yet.
			setSessionPending();
			setRoute('/expenses');

			const screen = render(LayoutHarness);

			await expect.element(screen.getByText('Loading…')).toBeVisible();
			await expect.element(screen.getByTestId('page-content')).not.toBeInTheDocument();
			await expect.element(screen.getByText('You are not logged in.')).not.toBeInTheDocument();
		});
	});

	describe('navigation', () => {
		it('shows the full authenticated nav (incl. Logout) when signed in', async () => {
			setSession(fakeSession());
			setRoute('/expenses');

			const screen = render(LayoutHarness);

			await expect
				.element(screen.getByRole('link', { name: 'Receipts', exact: true }))
				.toBeVisible();
			await expect.element(screen.getByRole('link', { name: 'Transactions' })).toBeVisible();
			await expect.element(screen.getByRole('link', { name: 'Reconciliation' })).toBeVisible();
			await expect.element(screen.getByRole('button', { name: 'Logout' })).toBeVisible();
		});

		it('shows only the Login link and no protected nav when signed out', async () => {
			setSession(null);
			setRoute('/login');

			const screen = render(LayoutHarness);

			await expect.element(screen.getByRole('link', { name: 'Login' })).toBeVisible();
			await expect
				.element(screen.getByRole('link', { name: 'Receipts', exact: true }))
				.not.toBeInTheDocument();
			await expect.element(screen.getByRole('button', { name: 'Logout' })).not.toBeInTheDocument();
		});

		it('preserves dateFrom/dateTo filters in nav link hrefs', async () => {
			setSession(fakeSession());
			setRoute('/expenses', '?dateFrom=2026-01-01&dateTo=2026-01-31');

			const screen = render(LayoutHarness);

			const receipts = screen.getByRole('link', { name: 'Receipts', exact: true });
			await expect
				.element(receipts)
				.toHaveAttribute('href', '/receipts?dateFrom=2026-01-01&dateTo=2026-01-31');
		});
	});

	describe('Profile link', () => {
		it('exposes the Profile link with its accessible label when signed in', async () => {
			setSession(fakeSession());
			setRoute('/expenses');

			const screen = render(LayoutHarness);

			await expect.element(screen.getByRole('link', { name: 'View profile' })).toBeVisible();
		});

		it('marks the Profile link as the current page when on /profile', async () => {
			setSession(fakeSession());
			setRoute('/profile');

			const screen = render(LayoutHarness);

			const profile = screen.getByRole('link', { name: 'View profile' });
			await expect.element(profile).toHaveAttribute('aria-current', 'page');
		});

		it('does not mark the Profile link current when on another route', async () => {
			setSession(fakeSession());
			setRoute('/expenses');

			const screen = render(LayoutHarness);

			const profile = screen.getByRole('link', { name: 'View profile' });
			await expect.element(profile).not.toHaveAttribute('aria-current');
		});

		it('hides the Profile link when signed out', async () => {
			// NOTE: the deleted layout-navigation.spec.ts asserted the Profile link is
			// "visible to all users" via a 200-char source-proximity heuristic — a false
			// positive. The link actually lives inside {#if $session}, so it is hidden
			// when signed out. This asserts the real behavior.
			setSession(null);
			setRoute('/login');

			const screen = render(LayoutHarness);

			await expect.element(screen.getByRole('link', { name: 'Login' })).toBeVisible();
			await expect
				.element(screen.getByRole('link', { name: 'View profile' }))
				.not.toBeInTheDocument();
		});
	});
});

/**
 * #{#bmb1a} Dev-only auto-login against the local stack.
 *
 * Exists for tooling that has no way to authenticate itself. Bombadil (the
 * property-based UI explorer — see docs/plans/2026-07-26-bombadil-property-testing-spike.md)
 * has no `--storage-state`, no cookie flag and no login helper, and our session
 * lives in localStorage rather than a header, so `--header` cannot help either.
 * Rather than add a no-session code path just for the test tool, we establish a
 * *real* Supabase session at boot: auth and RLS stay entirely intact.
 *
 * **Two independent gates, for two different reasons.**
 *
 * - `import.meta.env.DEV` is what removes the credential from the production
 *   bundle. Vite substitutes `false`, the early return becomes unconditional,
 *   and Rollup drops everything below it — including the imported password
 *   string. A runtime-only check would still *ship* the password.
 * - The loopback check on `PUBLIC_SUPABASE_URL` is what stops `npm run dev:remote`
 *   — which points at production and is still DEV — from firing known demo
 *   credentials at it.
 *
 * `npm run test:e2e` is unaffected: it runs `vite build && vite preview`, so DEV
 * is false and none of this is in that bundle.
 */
import { PUBLIC_SUPABASE_URL } from '$env/static/public';
import { supabase } from '$lib/supabaseClient';
import {
	DEMO_PASSWORD,
	OWNER_EMAIL,
	isLocalSupabaseUrl
} from '../../../scripts/demo/credentials.ts';

/**
 * Pages where being logged out is the whole point. Skipping them means a human
 * developer can still reach the login screen locally, and — more importantly —
 * that `logout()`'s redirect to `/login` is not immediately undone. Losing a
 * session stays visible instead of being silently papered over.
 */
const AUTH_ROUTES = ['/login', '/forgot-password', '/reset-password'];

/**
 * Sign in as the demo owner if nobody is signed in yet. Resolves once the
 * session exists (or once we've decided not to create one), so callers can
 * await it before deciding whether the user is authenticated.
 *
 * Never throws: a failure here must not take the app down. An unseeded database
 * is the common cause, so say so.
 */
export async function autoLoginForDev(): Promise<void> {
	if (!import.meta.env.DEV) return;
	if (!isLocalSupabaseUrl(PUBLIC_SUPABASE_URL)) return;
	if (AUTH_ROUTES.includes(window.location.pathname)) return;

	const { data } = await supabase.auth.getSession();
	if (data.session) return;

	const { error } = await supabase.auth.signInWithPassword({
		email: OWNER_EMAIL,
		password: DEMO_PASSWORD
	});

	if (error) {
		console.warn(
			`[dev auto-login] Could not sign in as ${OWNER_EMAIL}: ${error.message}\n` +
				'Seed the local stack with `npm run seed:demo` (or `npm run db:fresh`).'
		);
	}
}
